  ". Chaque équipe affiche sa forme récente. Un panneau \"course aux play-offs\" résume votre position, votre bilan et l'écart avec les places clés.": ". Cada equipe mostra sua fase recente. Um painel \"corrida pelos playoffs\" resume sua posição, sua campanha e a diferença para as posições-chave.",
