  "Avant chaque match, réglez trois choses pour votre équipe dans l'onglet Ordres. Tout s'enregistre automatiquement à chaque changement, et le bouton \"Enregistrer\", toujours visible en bas de la page, confirme l'enregistrement (\"Annuler\" revient aux ordres tels qu'à l'ouverture de la page). Dans le Calendrier, un match aux ordres validés affiche \"Modifier vos ordres\".": "Antes de cada jogo, ajuste três coisas para sua equipe na aba Ordens. Tudo é salvo automaticamente a cada alteração, e o botão \"Salvar\", sempre visível no fim da página, confirma o salvamento (\"Cancelar\" volta às ordens como estavam ao abrir a página). No Calendário, um jogo com ordens confirmadas mostra \"Editar suas ordens\".",
