  "Catégorie de fil d'actualité inconnue : {0}": "Categoria de feed de notícias desconhecida: {0}",
  "Catégorie de place inconnue : {0}.": "Categoria de lugar desconhecida: {0}.",
  "Ce bouton ne change RIEN au moteur du match : il choisit juste combien de réglages tactiques s'affichent à l'écran. Une équipe restée en Débutant joue avec des valeurs standards, exactement comme si elle avait activé le mode confirmé sans rien changer.": "Este botão NÃO muda NADA no motor do jogo: ele só escolhe quantos ajustes táticos aparecem na tela. Uma equipe que ficou no Iniciante joga com valores padrão, exatamente como se tivesse ativado o modo avançado sem mudar nada.",
  "Ce genre de match, ça se prépare mentalement dès le réveil, j'étais focus du début à la fin.": "Esse tipo de jogo a gente prepara mentalmente desde que acorda, eu estava focado do início ao fim.",
  "Ce joueur": "Este jogador",
  "Ce joueur est actuellement aux enchères sur le marché des transferts, ses caractéristiques sont donc visibles.": "Este jogador está em leilão no mercado de transferências, por isso seus atributos estão visíveis.",
  "Ce joueur est déjà au Hall of Fame.": "Este jogador já está no Hall of Fame.",
  "Ce joueur n'a jamais joué de match officiel pour le club.": "Este jogador nunca disputou um jogo oficial pelo clube.",
  "Ce joueur n'a pas demandé son transfert.": "Este jogador não pediu transferência.",
  "Ce joueur n'est plus dans cet effectif (vendu, ou transféré).": "Este jogador não está mais neste elenco (vendido ou transferido).",
  "Ce lien n'est pas valide : demande un nouveau lien privé à l'organisateur de la ligue.": "Este link não é válido: peça um novo link privado ao organizador da liga.",
  "Ce maillot est déjà retiré.": "Esta camisa já está aposentada.",
  "Ce nom de salle n'est pas autorisé.": "Este nome de ginásio não é permitido.",
  "Ce nom n'est pas autorisé.": "Este nome não é permitido.",
  "Ce que ça veut dire": "O que isso significa",
  "Ce que la ligue privée ne touche pas": "O que a liga privada não altera",
  "Ce qui la fait baisser": "O que faz cair",
  "Ce qui la fait monter": "O que faz subir",
  "Ce rapport est déjà débloqué et à jour.": "Este relatório já está desbloqueado e atualizado.",
  "Ce réglage est toujours visible, quel que soit votre niveau tactique. En Adaptatif, l'équipe qui mène large lève le pied dès le 3e quart-temps, les titulaires sortent au 4e quart-temps à 18 points d'écart (forme ménagée), et le rythme s'accélère légèrement dans les 5 dernières minutes d'un match serré.": "Este ajuste está sempre visível, qualquer que seja seu nível tático. No Adaptativo, a equipe que vence com folga tira o pé do acelerador a partir do 3º quarto, os titulares saem no 4º quarto com 18 pontos de diferença (forma poupada), e o ritmo acelera levemente nos 5 últimos minutos de um jogo equilibrado.",
  "Ce soir, tout est rentré naturellement, mes coéquipiers m'ont trouvé aux bons endroits toute la rencontre.": "Esta noite tudo entrou naturalmente, meus companheiros me acharam nos lugares certos o jogo inteiro.",
  "Ce titre appartient à tout le monde au club, on va rester humbles et continuer à travailler comme si de rien n'était.": "Este título pertence a todo mundo no clube, vamos manter a humildade e continuar trabalhando como se nada tivesse acontecido.",
  "Ce titre de champion face à {opponent} en finale récompense tout le travail accompli cette saison, une immense fierté pour tout le club.": "Este título de campeão contra {opponent} na final recompensa todo o trabalho feito nesta temporada, um orgulho imenso para todo o clube.",
  "Ce titre face à {opponent} appartient à tout le club, des joueurs jusqu'au dernier membre du staff, on ne l'oubliera jamais.": "Este título contra {opponent} pertence ao clube inteiro, dos jogadores até o último membro do staff, nunca vamos esquecê-lo.",
  "Ce titre représente une immense fierté pour tout le club, du staff aux joueurs en passant par les supporters.": "Este título representa um orgulho imenso para todo o clube, do staff aos jogadores, passando pelos torcedores.",
  "Ce titre représente une nouvelle étape pour ce club, et on compte bien ne pas s'arrêter là la saison prochaine.": "Este título representa uma nova etapa para este clube, e não pretendemos parar por aqui na próxima temporada.",
  "Ce trigramme est déjà utilisé par un autre club de la ligue.": "Esta sigla já é usada por outro clube da liga.",
  "Ce trigramme n'est pas autorisé.": "Esta sigla não é permitida.",
  "center": "center",
