  "Cercle / raquette": "Aro / garrafão",
  "Ces infrastructures se financent chacune indépendamment : inutile d'attendre d'avoir fini d'en payer une pour commencer la suivante si le budget suit.": "Essas infraestruturas são financiadas de forma independente: não é preciso terminar de pagar uma para começar a próxima, se o orçamento permitir.",
  "Cet adversaire a rejoué depuis ton dernier déblocage : les données ont changé.": "Este adversário jogou de novo desde o seu último desbloqueio: os dados mudaram.",
  "Cet emplacement a déjà un sponsor.": "Este espaço já tem um patrocinador.",
  "Cette carte montre le prochain match avec un compte à rebours ; sur chaque ligne, le bouton Ordres (ou Modifier vos ordres) prépare le match correspondant.": "Este card mostra o próximo jogo com uma contagem regressiva; em cada linha, o botão Ordens (ou Editar suas ordens) prepara o jogo correspondente.",
  "Cette défaite contre {opponent} à mi-saison est une bonne piqûre de rappel, on doit rester humbles et travailler encore plus dur pour la suite.": "Esta derrota para {opponent} no meio da temporada é um bom lembrete, precisamos manter a humildade e trabalhar ainda mais para o que vem.",
  "Cette défaite contre {opponent} arrive à un moment charnière de la saison, on va en tirer les leçons avant d'attaquer la seconde moitié du calendrier.": "Esta derrota para {opponent} chega num momento decisivo da temporada, vamos tirar as lições antes de encarar a segunda metade do calendário.",
  "Cette défaite contre {opponent} ne change rien à nos ambitions pour la seconde moitié de saison, on reste le favori de cette division.": "Esta derrota para {opponent} não muda nada nas nossas ambições para a segunda metade da temporada, continuamos sendo os favoritos desta divisão.",
  "Cette défaite contre {opponent} pour terminer la saison régulière nous rappelle qu'il reste encore des choses à corriger avant la suite.": "Esta derrota para {opponent} para fechar a temporada regular nos lembra que ainda há coisas a corrigir antes do que vem.",
  "Cette défaite en finale contre {opponent} est difficile à digérer, mais on reviendra chercher ce titre la saison prochaine, sans exception.": "Esta derrota na final para {opponent} é difícil de digerir, mas vamos voltar para buscar este título na próxima temporada, sem exceção.",
  "Cette défaite en finale contre {opponent} est une déception, mais atteindre la finale reste une très belle saison pour ce groupe.": "Esta derrota na final para {opponent} é uma decepção, mas chegar à final continua sendo uma temporada muito bonita para este grupo.",
  "Cette défaite en finale fait partie du sport, on va rester humbles et repartir travailler dès la saison prochaine.": "Esta derrota na final faz parte do esporte, vamos manter a humildade e voltar a trabalhar já na próxima temporada.",
  "Cette défaite en finale reste une bonne saison pour ce club, on va essayer de franchir ce dernier palier la saison prochaine.": "Mesmo com esta derrota na final, foi uma boa temporada para este clube, vamos tentar dar este último passo na próxima temporada.",
  "Cette défaite ne représente rien de plus qu'un contretemps, ce club reviendra chercher ce titre très vite.": "Esta derrota não passa de um contratempo, este clube vai voltar para buscar este título muito em breve.",
  "Cette dernière défaite de saison régulière contre {opponent} n'entache en rien notre saison, on sait qu'on est prêts pour la suite.": "Esta última derrota da temporada regular para {opponent} não mancha em nada a nossa temporada, sabemos que estamos prontos para o que vem.",
  "Cette élimination en demi-finale contre {opponent} est frustrante après une belle saison, on va analyser calmement ce qui a manqué.": "Esta eliminação na semifinal para {opponent} é frustrante depois de uma bela temporada, vamos analisar com calma o que faltou.",
  "Cette enchère est déjà terminée.": "Este leilão já terminou.",
  "Cette équipe a déjà été scoutée cette saison": "Esta equipe já foi observada nesta temporada",
  "Cette équipe a déjà été scoutée cette saison ({0}/{1} caractéristiques révélées, définitif), impossible de la rescouter avant la saison prochaine, même avec un meilleur analyste.": "Esta equipe já foi observada nesta temporada ({0}/{1} atributos revelados, definitivo), impossível observá-la de novo antes da próxima temporada, mesmo com um analista melhor.",
  "Cette équipe a déjà été scoutée cette saison.": "Esta equipe já foi observada nesta temporada.",
