  "L'adversaire ne peut pas aligner un cinq de départ complet : vous gagnerez automatiquement par forfait (20-0) à l'heure prévue.": "O adversário não consegue escalar um quinteto inicial completo: você vencerá automaticamente por W.O. (20-0) no horário previsto.",
  "L’affiche": "O confronto",
  "L'alchimie (0 à 100, visible sur le Tableau de bord et en tête de l'Effectif) mesure la cohésion du groupe. Elle agit sur TOUTE l'équipe en match, de -6 % (vestiaire fracturé) à +6 % (alchimie parfaite). Paliers : Vestiaire fracturé (moins de 25), Tensions dans le groupe (25-44), Cohésion correcte (45-64), Bonne cohésion (65-84), Alchimie parfaite (85 et plus).": "A química (0 a 100, visível no Painel e no topo do Elenco) mede a coesão do grupo. Ela age sobre TODO o time nas partidas, de -6 % (vestiário rachado) a +6 % (química perfeita). Níveis: Vestiário rachado (abaixo de 25), Tensões no grupo (25-44), Entrosamento razoável (45-64), Bom entrosamento (65-84), Química perfeita (85 ou mais).",
  "L'ambiance du club": "O clima do clube",
  "L’attaque tourne à plein régime.": "O ataque está funcionando a todo vapor.",
  "L’AVANT-": "O PRÉ-",
  "L’AVANT-MATCH": "O PRÉ-JOGO",
  "L'effectif jeunes est déjà complet (15 stagiaires).": "O elenco de base já está completo (15 jovens).",
  "L'émission de la mi-temps": "O programa do intervalo",
  "l'emporte de": "vence por",
  "L'entraîneur n'a aucun effet sur les matchs : il accélère uniquement la progression à l'entraînement (+6% par niveau). On ne l'achète plus à prix fixe : plusieurs candidats de niveaux variés sont proposés en permanence sur un": "O treinador não tem nenhum efeito nas partidas: ele apenas acelera a evolução nos treinos (+6% por nível). Ele não é mais comprado a preço fixo: vários candidatos de níveis variados estão sempre disponíveis em um",
  "L'entre-deux est remporté par {0}.": "A bola ao alto é vencida por {0}.",
  "L'humeur des supporters (0 à 100, onglet dédié) influence le remplissage de votre salle et la tolérance au prix du billet : des supporters contents viennent plus facilement et acceptent des prix plus élevés. Elle évolue avec chaque résultat (victoire ou défaite, à domicile ou à l'extérieur), vos tons en interview de jalon, et dérive lentement selon que le prix des billets est jugé raisonnable ou non.": "O humor da torcida (0 a 100, aba própria) influencia a ocupação do seu ginásio e a tolerância ao preço do ingresso: torcedores satisfeitos vêm com mais facilidade e aceitam preços mais altos. Ele muda a cada resultado (vitória ou derrota, em casa ou fora), com os tons das suas entrevistas de marco, e varia lentamente conforme o preço dos ingressos seja considerado razoável ou não.",
  "L'image de votre salle actuelle. Une salle plus grande accueille plus de spectateurs à chaque match à domicile, donc plus de recettes de billetterie.": "A imagem do seu ginásio atual. Um ginásio maior recebe mais espectadores a cada partida em casa, ou seja, mais receita de bilheteria.",
  "L'objectif de saison": "O objetivo da temporada",
  "L'objectif est clair pour cette saison : on vise le haut de tableau, on ne se fixe aucune limite.": "O objetivo está claro para esta temporada: vamos brigar pelo topo da tabela, sem nenhum limite.",
  "L'objectif est de construire une équipe solide et de rester compétitifs sur la durée de la saison, sans se fixer de chiffre précis pour l'instant.": "O objetivo é montar um time sólido e continuar competitivo ao longo da temporada, sem fixar um número preciso por enquanto.",
  "L'onglet": "A aba",
  "La": "A",
  "La confiance du joueur, jamais liée à la fatigue. Alimentée par le ton choisi lors des interviews de jalon (voir l'onglet Humeur des supporters) : Agressif amplifie le résultat, Mesuré reste modéré, Humble limite la casse en cas de défaite.": "A confiança do jogador, nunca ligada ao cansaço. Alimentada pelo tom escolhido nas entrevistas de marco (veja a aba Humor da torcida): Agressivo amplifica o resultado, Comedido se mantém moderado, Humilde limita o estrago em caso de derrota.",
  "La Coupe": "A Copa",
  "La Coupe n'existe que pour la ligue multi-manager (elle n'est pas jouée en carrière solo pour l'instant).": "A Copa só existe na liga multi-manager (ela não é disputada na carreira solo por enquanto).",
  "La courbe apparaîtra après le premier événement.": "O gráfico vai aparecer após o primeiro evento.",
