  "Le barrage de relégation a été calculé. Les play-offs commencent, un match à la fois, en direct, sur plusieurs jours réels.": "A repescagem de rebaixamento foi calculada. Os playoffs começam, uma partida por vez, ao vivo, ao longo de vários dias reais.",
