  "Les play-offs sont en cours, sur plusieurs jours réels. Revenez pour votre prochain match, ou suivez leur progression ici.": "Os playoffs estão em andamento, ao longo de vários dias reais. Volte para a sua próxima partida ou acompanhe o andamento aqui.",
