  "liste tous vos matchs de la saison, championnat et Coupe confondus, groupés par mois et triés par date et heure réelle. Filtres Tous, Domicile, Extérieur et À venir ; \"vs\" devant l'adversaire signifie à domicile, \"@\" à l'extérieur. À droite : la carte du prochain match (compte à rebours et bouton des ordres) et le bilan de la saison (bilan, classement, différence de points, domicile/extérieur, forme sur les 5 derniers matchs). Les horaires restent fixes, même au changement d'heure.": "lista todas as suas partidas da temporada, campeonato e Copa juntos, agrupadas por mês e ordenadas por data e horário reais. Filtros Todas, Casa, Fora e Próximas; “vs” antes do adversário significa em casa, “@” fora. À direita: o cartão da próxima partida (contagem regressiva e botão de ordens) e o resumo da temporada (campanha, classificação, saldo de pontos, casa/fora, forma nas últimas 5 partidas). Os horários permanecem fixos, mesmo na mudança de horário de verão.",
