  "MODE ACCÉLÉRÉ (TEST) ACTIVÉ (BASKET_FAST_CALENDAR=1) : un match toutes les 5h, entraînement + semaine économique tous les 2 matchs — les nouvelles carrières/ligues démarrées à partir de maintenant en profitent ; une ligue déjà en cours garde son rythme actuel.": "MODO ACELERADO (TESTE) ATIVADO (BASKET_FAST_CALENDAR=1): um jogo a cada 5h, treino + semana econômica a cada 2 jogos — as novas carreiras/ligas iniciadas a partir de agora aproveitam isso; uma liga já em andamento mantém o ritmo atual.",
