  "Nom, poste, taille et salaire des joueurs adverses sont toujours visibles, mais leurs caractéristiques restent cachées tant qu'elles n'ont pas été révélées : l'onglet Caractéristiques de l'effectif adverse n'affiche QUE les caracs révélées. Recrutez un": "Nome, posição, altura e salário dos jogadores adversários estão sempre visíveis, mas os atributos deles ficam ocultos enquanto não forem revelados: a aba Atributos do elenco adversário mostra APENAS os atributos revelados. Contrate um",
