  "O'Brien": "O'Brien",
  "Objectif de la saison largement dépassé ({0} espéré) : l'équipe termine avec {1} ! Les supporters sont aux anges.": "Objetivo da temporada amplamente superado ({0} esperado): o time termina com {1}! A torcida está nas nuvens.",
  "Objectif de la saison manqué ({0}) : l'équipe termine avec {1}. Les supporters sont déçus.": "Objetivo da temporada não alcançado ({0}): o time termina com {1}. A torcida está decepcionada.",
  "Objectif de la saison manqué ({0}) : l'équipe termine avec une relégation. Les supporters sont déçus. ({1}).": "Objetivo da temporada não alcançado ({0}): o time termina rebaixado. A torcida está decepcionada. ({1}).",
  "Objectif de la saison rempli ({0}) : l'équipe termine avec {1}, exactement ce qui était demandé.": "Objetivo da temporada cumprido ({0}): o time termina com {1}, exatamente o que foi pedido.",
