  "Offre refusée.": "Oferta recusada.",
  "offRebStyle": "offRebStyle",
  "Offres reçues": "Ofertas recebidas",
  "ok": "ok",
  "Oliveira": "Oliveira",
  "on": "on",
  "On a fait la moitié du chemin avec cette victoire contre {opponent}, mais rien n'est acquis, il reste encore beaucoup de travail avant la fin de saison.": "Fizemos metade do caminho com esta vitória contra {opponent}, mas nada está garantido, ainda há muito trabalho até o fim da temporada.",
  "On aborde la suite avec humilité, chaque adversaire mérite le plus grand respect à ce stade de la saison.": "Encaramos o que vem pela frente com humildade, cada adversário merece o maior respeito nesta altura da temporada.",
  "On aborde la suite avec l'envie de corriger ce qui n'a pas fonctionné ces dernières semaines.": "Encaramos o que vem pela frente com vontade de corrigir o que não funcionou nas últimas semanas.",
  "On aborde la suite avec la certitude d'avoir le niveau pour aller loin, sans aucune pression particulière.": "Encaramos o que vem pela frente com a certeza de ter nível para ir longe, sem nenhuma pressão especial.",
  "On aborde la suite avec la même confiance, cette fin de saison régulière ne change rien à nos ambitions.": "Encaramos o que vem pela frente com a mesma confiança, este final de temporada regular não muda nada nas nossas ambições.",
  "On aborde la suite en sachant qu'il reste beaucoup de travail, on ne change rien à notre état d'esprit.": "Encaramos o que vem pela frente sabendo que ainda há muito trabalho, não mudamos nada na nossa mentalidade.",
  "On aborde la suite sereinement, en essayant de garder cette dynamique le plus longtemps possible.": "Encaramos o que vem pela frente com tranquilidade, tentando manter esse embalo o máximo possível.",
  "On accepte cette élimination avec humilité et on va travailler encore plus dur pour revenir plus forts.": "Aceitamos esta eliminação com humildade e vamos trabalhar ainda mais duro para voltar mais fortes.",
  "On cherche un partenaire stable, pas un feu de paille.": "Buscamos um parceiro estável, não fogo de palha.",
  "On compte énormément sur {player} pour tirer l'équipe vers le haut, c'est un joueur fait pour ce genre de responsabilités.": "Contamos muito com {player} para puxar o time para cima, é um jogador feito para esse tipo de responsabilidade.",
  "On doit se remettre en question collectivement et travailler encore plus dur pour la seconde moitié de saison.": "Precisamos nos questionar coletivamente e trabalhar ainda mais duro na segunda metade da temporada.",
  "On envoie un message clair à toute la ligue en éliminant {opponent} en demi-finale, la prochaine étape ne nous fait absolument pas peur.": "Mandamos um recado claro para toda a liga ao eliminar {opponent} na semifinal, a próxima etapa não nos assusta nem um pouco.",
  "On ne se fixe pas d'objectif chiffré, l'idée est de progresser ensemble match après match, en restant les pieds sur terre.": "Não estabelecemos uma meta numérica, a ideia é evoluir juntos jogo após jogo, mantendo os pés no chão.",
  "On passe le cap de la mi-saison sur la meilleure dynamique possible, et {opponent} vient encore de le confirmer : personne ne veut vraiment nous affronter en ce moment.": "Passamos da metade da temporada no melhor momento possível, e {opponent} acabou de confirmar isso: ninguém quer muito nos enfrentar agora.",
  "On prépare la suite avec la même confiance, on n'a pas fait tout ce chemin pour s'arrêter en si bon chemin.": "Preparamos o que vem pela frente com a mesma confiança, não chegamos até aqui para parar agora.",
  "On savait qu'on était la meilleure équipe de la division, ce titre face à {opponent} en finale ne fait que le confirmer.": "Sabíamos que éramos o melhor time da divisão, este título contra {opponent} na final só confirma isso.",
  "On se retrouve après une courte pause…": "Voltamos depois de um breve intervalo…",
  "On termine la saison régulière sur cette victoire contre {opponent}, et on aborde les échéances qui arrivent avec la plus grande confiance qui soit.": "Terminamos a temporada regular com esta vitória contra {opponent} e encaramos os próximos desafios com toda a confiança do mundo.",
  "On termine la saison régulière sur une défaite décevante contre {opponent}, mais le bilan global de l'année reste ce qui compte le plus.": "Terminamos a temporada regular com uma derrota decepcionante contra {opponent}, mas o balanço geral do ano é o que mais importa.",
  "On tire un trait sur cette élimination et on prépare déjà la revanche pour la saison prochaine, sans complexe.": "Viramos a página desta eliminação e já preparamos a revanche para a próxima temporada, sem medo.",
  "On va analyser calmement cette élimination et en tirer les enseignements pour progresser encore.": "Vamos analisar com calma esta eliminação e tirar lições dela para continuar evoluindo.",
  "On va continuer à travailler dans la continuité, avec quelques ajustements tactiques pour la seconde moitié.": "Vamos continuar trabalhando na mesma linha, com alguns ajustes táticos para a segunda metade.",
  "On va continuer à travailler humblement, rien n'est jamais acquis dans ce championnat.": "Vamos continuar trabalhando com humildade, nada é garantido neste campeonato.",
  "On va préparer la suite avec sérieux, sans s'enflammer, il reste encore une marche à franchir.": "Vamos preparar o que vem pela frente com seriedade, sem empolgação, ainda falta mais um degrau.",
  "On va préparer la suite pas à pas, sans se projeter trop vite sur la suite.": "Vamos preparar o que vem pela frente passo a passo, sem pensar longe demais.",
  "On va revoir certains détails à l'entraînement pour repartir sur de meilleures bases en seconde moitié de saison.": "Vamos revisar alguns detalhes nos treinos para recomeçar em bases melhores na segunda metade da temporada.",
  "On veut vous voir plus haut que ce que le CA demande.": "Queremos ver você mais alto do que a diretoria pede.",
  "On vous suit sur l'objectif de la saison.": "Estamos acompanhando você no objetivo da temporada.",
