  "Pénétration": "Infiltração",
  "Pénétration, Création de tir, Interceptions, Vitesse, Accélération, Force, Détente, Décision, Sang-froid, Détermination, Discipline et Vision ont elles aussi leur mécanisme. La Pénétration aide à se créer un accès à la raquette. La Création de tir est le facteur principal de la qualité d'ouverture d'un tir. Les Interceptions pèsent dans le choix du voleur de balle. La Vitesse et l'Accélération déclenchent des contre-attaques et aident à battre son défenseur au premier pas. La Force et la Détente renforcent le rebond et le contre. La Décision réduit les pertes de balle ; la Vision améliore le choix du passeur. Le Sang-froid et la Détermination agissent comme le Mental. La Discipline réduit les fautes en défense ; un défenseur peu discipliné risque une faute antisportive, un défenseur peu serein une faute technique : deux techniques, deux antisportives, ou une de chaque dans le même match valent exclusion.": "Infiltração, Criação de arremesso, Roubos de bola, Velocidade, Aceleração, Força, Impulsão, Tomada de decisão, Sangue-frio, Determinação, Disciplina e Visão de jogo também têm seu próprio mecanismo. A Infiltração ajuda a abrir caminho até o garrafão. A Criação de arremesso é o fator principal da qualidade de abertura de um arremesso. Os Roubos de bola pesam na escolha de quem rouba a bola. A Velocidade e a Aceleração geram contra-ataques e ajudam a passar pelo defensor no primeiro passo. A Força e a Impulsão reforçam o rebote e o toco. A Tomada de decisão reduz os desperdícios de bola; a Visão de jogo melhora a escolha do passador. O Sangue-frio e a Determinação funcionam como o Mental. A Disciplina reduz as faltas na defesa; um defensor pouco disciplinado arrisca uma falta antidesportiva, um defensor pouco tranquilo uma falta técnica: duas técnicas, duas antidesportivas ou uma de cada no mesmo jogo resultam em expulsão.",
