  "Polyvalent (2 caractéristiques, chacune à 62 %)": "Versátil (2 atributos, cada um a 62%)",
  "Deux types de programmes. Spécialisé : une seule compétence, à plein rendement. Polyvalent : deux compétences liées en même temps (par exemple Tir extérieur = Tir à mi-distance + Tir à 3 points), chacune progressant à 62 % du rythme d'un programme spécialisé. Au total, on progresse un peu plus (124 % contre 100 %), mais réparti sur deux compétences.": "Dois tipos de programa. Especializado: uma única habilidade, com rendimento total. Versátil: duas habilidades relacionadas ao mesmo tempo (por exemplo, Arremesso de fora = Arremesso de média distância + Arremesso de 3 pontos), cada uma evoluindo a 62% do ritmo de um programa especializado. No total, a evolução é um pouco maior (124% contra 100%), mas dividida entre duas habilidades.",
