  "Un jeune faible mais à fort potentiel, bien entraîné, peut dépasser un joueur déjà bon dont le potentiel est presque atteint. Le détail des paliers est dans le Guide.": "Um jovem fraco mas com alto potencial, bem treinado, pode superar um jogador já bom cujo potencial está quase atingido. O detalhe dos níveis está no Guia.",
