  "Votre équipe maîtrise plus ou moins chaque option tactique : une jauge par priorité offensive, par défense et par rythme (visible dans le menu \"Aspect travaillé\" de l'Entraînement). La maîtrise des options que vous jouez agit sur toute l'équipe en match, jusqu'à +/-6 %, en plus de l'alchimie.": "Sua equipe domina mais ou menos cada opção tática: um medidor por prioridade ofensiva, por defesa e por ritmo (visível no menu \"Aspecto trabalhado\" do Treino). O domínio das opções que você usa age sobre toda a equipe em jogo, até +/-6 %, além da química.",
