  "(jeu intérieur, rebond, contre, défense intérieure) ou": "(jogo interior, rebote, toco, defesa interior) ou",
  "(défense extérieure, interceptions). Chaque semaine, tous les joueurs non blessés progressent un peu sur ces caractéristiques, qu'ils aient joué ou non, en plus de l'entraînement des fondamentaux. Moins sa spécialité compte de caractéristiques, plus chacune progresse vite. L'effet est surtout sensible chez les jeunes, il dépend aussi du poste et du gabarit de chaque joueur, et il est renforcé par l'entraîneur principal.": "(defesa de perímetro, roubos de bola). Toda semana, todos os jogadores não lesionados evoluem um pouco nesses atributos, tenham jogado ou não, além do treino de fundamentos. Quanto menos atributos a especialidade abrange, mais rápido cada um evolui. O efeito é sentido principalmente pelos jovens, também depende da posição e do biotipo de cada jogador, e é reforçado pelo treinador principal.",
  "Entraîneur, entraîneur adjoint, analyste vidéo, recruteur, médecin, kiné : chacun a 5 niveaux, avec un coût et un effet croissants. L'analyste vidéo révèle par exemple certaines caractéristiques cachées des joueurs adverses avant un match, et le kiné réduit le risque de blessure.": "Treinador, assistente técnico, analista de vídeo, recrutador, médico, fisioterapeuta: cada um tem 5 níveis, com custo e efeito crescentes. O analista de vídeo, por exemplo, revela alguns atributos ocultos dos jogadores adversários antes de um jogo, e o fisioterapeuta reduz o risco de lesão.",
  "staff médical": "equipe médica",
  "s'achète sur le même marché aux enchères, avec le même salaire qui grimpe chaque semaine. Le": "é contratado no mesmo mercado de leilões, com o mesmo salário que sobe toda semana. O",
  "raccourcit la durée des nouvelles blessures. Le": "encurta a duração das novas lesões. O",
  "suit tout l'effectif : la forme physique remonte plus vite chaque jour et le risque de blessure en match baisse (il s'ajoute à l'effet de la salle de musculation). Plus leur niveau est élevé, plus l'effet est fort.": "acompanha todo o elenco: a forma física se recupera mais rápido a cada dia e o risco de lesão em jogo diminui (somando-se ao efeito da sala de musculação). Quanto maior o nível, mais forte o efeito.",
